from collections import defaultdict

def find_satisfying_binary_tree():
    # Import your required libraries here if needed

    n = int(input())
    c = int(input())
    edges = []
    for _ in range(c):
        ai = int(input())
        bi = int(input())
        direction = input()
        if direction == 'LEFT':
            edges.append((ai, bi-1))
        else:
            edges.append((ai-1, ai+1))

    # Check if it's possible to form a binary tree with \(n\) nodes
    if n % 2 == 0:
        return 'IMPOSSIBLE'
    else:
        left_nodes = defaultdict(int)
        for _, right in edges:
            left_nodes[right] += 1

        # If there are more than one left child for any node, it's impossible to form a valid binary tree
        if max(left_nodes.values()) > 1:
            return 'IMPOSSIBLE'
        else:
            # If the tree exists, print it using in-order traversal
            return ' '.join([str(i+1) for i in range(n)])

