import sys

MOD = 10**9 + 7

def count_configurations(n, initial_population):
    if n == 1:
        return 1
    prefix_sum = [0] * (n + 1)
    prefix_sum[0] = 1
    for i in range(n):
        prefix_sum[i + 1] = (prefix_sum[i] + (i > 0 and initial_population[i] == initial_population[i - 1])) % MOD
    dp = [[0] * (1 << n) for _ in range(n + 1)]
    dp[0][0] = 1
    for i in range(1, n + 1):
        for prev in range((1 << n) - 1, -1, -1):
            for j, char in enumerate(prefix_sum[i], i):
                if j == n and dp[i - 1][prev] != 0:
                    dp[i][prev] = (dp[i][prev] + dp[i - 1][prev]) % MOD
                if j > 0:
                    new_char = char if prev & (1 << j - 1) else "0" if init_population[j - 1] == "0" else "1"
                    dp_max = max((prev | (1 << j)), (prev & (1 << j - 1))) if j > 0 else prev
                    dp[i][prev | (1 << j)] = (dp[i][prev | (1 << j)] + dp[i - 1][dp_max]) % MOD
    return sum(dp[n][-1]) % MOD

