# Modular Exponentiation for large numbers
def mod_exp(base, exponent, modulus):
    result = 1
    base = base % modulus
    while exponent > 0:
        if (exponent & 1) == 1:
            result = (result * base) % modulus
        exponent = exponent >> 1
        base = (base * base) % modulus
    return result

class TofuRepository:
    def __init__(self, number_of_strings, base, limit):
        self.base = base
        self.terms = [[] for _ in range(number_of_strings)]
        self.values = [0] * number_of_strings
        self.limit = limit

    def read_number(self, digits):
        l = len(digits)
        value = 0
        for i, digit in enumerate(digits):
            value += pow(10, l - i - 1) * digit
        return value

    def process_tofu_owners(self, number_strings):
        self.terms = [[] for _ in range(len(self.terms))]
        for num_string in number_strings:
            value = self.read_number(num_string.split())
            index = value % (self.base ** self.limit)
            for i in range(self.limit):
                if self.values[i] != 0 and (self.values[i] + index) % self.base ** i == 0:
                    self.terms[value % self.base ** self.limit].append(i)
                    break
                self.values[i] = value
