def find_starting_move(n, m, cuts):
    # Sort cuts based on y and then x coordinates
    cuts.sort(key=lambda x: (x[1], x[0]))

    # Dictionary to map y to the first x-coordinate above it
    y_max = {v: k for k, v in enumerate(cuts, start=1)}

    for x, ybi, xei, yei in cuts:
        if x < n and ybi < y_max[yi] and yei >= y_max[yi+1]:
            # Check if there's a path from x to n without going below y_max[yi+1] in the x-direction
            while x + 1 <= n and ybi < y_max[yi] and (yei in y_max or yei >= y_max[yi+1]):
                ybi += 1
                yei += 1
            return [x, ybi, xei, yei]
        elif x > 0 and yei > y_max[yi] and yei < y_max[yi+1]:
            # Check if there's a path from x-1 to 0 without going above y_max[yi+1] in the x-direction
            while x - 1 > 0 and ybi > y_max[yi] and (yei in y_max or yei < y_max[yi+1]):
                ybi -= 1
                yei -= 1
            return [x, ybi, xei, yei]
