def find_path(graph: List[List[int]], start: int) -> Tuple[int, List[int]]:
    visited = [False] * len(graph)
    queue = [start]
    visited[start] = True
    path = []

    while queue:
        current = queue.pop(0)
        path.append(current)

        for neighbor in range(len(graph[current])):
            if not visited[neighbor] and graph[current][neighbor] == 1:
                visited[neighbor] = True
                queue.append(neighbor)

    return len(path) - 1, path if not visited[-1] or start != 0 else None

