                    next_arrangement[i], next_arrangement[j] = next_arrangement[j], next_arrangement[i]
        for arrangement in arrangements[::-1]:
            for i in range(n):
                if arrangement[i] == -1:
                    arrangement[i] = j + 1
        if all(0 <= arr < n for arr in next_arrangement):
            arrangements.append(next_arrangement)
            break
    if all(0 <= arr < n for arr in arrangements[-1]):
        return arrangements[-1]
    else:
        return ["The times have changed"]

