def bfs_tree(preorder_nodes, constraints):
    constraints.sort(key=lambda x: x[0])
    result = []
    stack = []
    current = 0
    for node in preorder_nodes:
        while current < len(constraints) and constraints[current][0] == node:
            constraint = constraints[current]
            if constraint[2] == "left":
                if len(stack) > constraint[1]:
                    parent = stack.pop()
                    result.append(parent)
                    stack.append(node)
                    stack.append(parent)
                else:
                    result.append(node)
                    current += 1
            else:
                to_append = node
                for idx in range(len(stack)-1, 0, -1):
                    if node < stack[idx-1]:
                        to_append = stack.pop()
                        stack.append(node)
                        stack.append(to_append)
                        break
                else:
                    if len(stack) > constraint[1]:
                        parent = stack.pop()
                        result.append(parent)
                        stack.append(node)
                        stack.append(parent)
                        stack.append(to_append)
                    else:
                        result.append(node)
                        stack.append(to_append)
                        current += 1
        if stack:
            current = len(constraints)
            stack.append(node)
