class AntSimulation:
    def __init__(self, n, m, t):
        self.n = n
        self.m = m
        self.t = t
        self.positions = [0] * self.n
        self.directions = [0] * self.n

    def simulate(self):
        for i in range(self.n):
            if self.directions[i] == 'L':
                self.positions[i] -= 1 if self.positions[i] > 0 else -self.positions[i]
            else:
                self.positions[i] += 1 if self.positions[i] < self.m else -self.positions[i]

        collisions = 0
        while collisions > 0:
            collisions = 0
            for i in range(self.n):
                if self.directions[i] == 'L' and self.positions[i] == 0:
                    self.directions[i] = 'R'
                    self.positions[i] = self.m - 1
                    collisions += 1
                elif self.directions[i] == 'R' and self.positions[i] == self.m - 1:
                    self.directions[i] = 'L'
                    self.positions[i] = 1
                    collisions += 1

        for i in range(self.n):
            if self.directions[i] == 'L':
                self.positions[i] = max(0, self.positions[i])  # Wrap around the circle

        return self.positions

