    constraints = []
    for i in range(c):
        ai, bi, direction = map(str, input().split())
        constraints.append((ai, bi, direction))

    valid_trees = []

    def is_valid_tree(nodes):
        if len(nodes) != n:
            return False

        validate = []
        nodes = list(nodes)
        for i in range(n):
            if nodes[i] < 1 or nodes[i] > n:
                return False

        # Pre-order traversal of tree
        for node in nodes:
            validate.append(node)

        # Prepare constraints
        constraints_node = []
        for constraint in constraints:
            ai, bi, direction = constraint
            if direction == 'LEFT':
                if ai in nodes:
                    constraints_node.append((ai, bi))
                elif ai + 1 <= n and (ai + 1, bi, 'RIGHT') in constraints:
                    constraints_node.append((ai + 1, bi))
            else:  # direction == 'RIGHT'
                if bi in nodes:
                    constraints_node.append((ai, bi))
                elif bi + 1 <= n and (ai, bi + 1, 'LEFT') in constraints:
                    constraints_node.append((ai, bi + 1))

        # Check constraints
        for ai, bi in constraints_node:
            if b + 1 <= n:
                if nodes.index(bi + 1) > nodes.index(ai):
                    continue
            if a + 1 <= n:
                if nodes.index(a - 1) > nodes.index(ai):
                    continue
            return False

        valid_trees.append(nodes)
        return True

    # Test all possible binary trees
    for a in range(1, n + 1):
        for b in range(1, n + 1):
            if a != b:
                valid_trees = [f for f in valid_trees if is_valid_tree(f)]
                if not valid_trees:
                    valid_trees = [f for f in valid_trees if is_valid_tree([b for b in range(1, n + 1)] + [a])]

    if not valid_trees:
        print("IMPOSSIBLE")
    else:
        print(' '.join([str(node) for nodes in valid_trees for node in nodes]))
