def subsequence_decode(sequence, restrictions, n):
    # Generate distinct permutations respecting the sequence and restrictions
    return tuple(p for p in permutations(range(1, n+1)) if all(sequence.index(s) <= sequence.index(j) for s, j in restrictions))

def get_guc_arrangement(n, y, m, restrictions):
    permutation = list(range(1, n+1))
    max_permutation = list(range(1, n+1))

    while y > 2001:
        for permutation in subsequence_decode(permutation, restrictions, n-1):
            if max_permutation != permutation:
                max_permutation = list(permutation)
                y -= 1
        if y <= 2001:
            break

    return 'The times have changed' if y <= 2000 else subsequence_decode(max_permutation, restrictions, n-1)

