def count_ways(n, ratings, paths):
    mod = 10**9 + 7
    @lru_cache(None)
    def dp(i):
        if i >= n:
            return 1
        ways = dp(i + 1)
        for j in range(1, ratings[i] + 1):
            if dp(j) and dp(j - 1):
                ways = (ways + dp(j - 1)) % mod
        return ways

    max_min = max(ratings)
    min_max = 1
    for i in range(n):
        if ratings[i] > max_min:
            max_min = ratings[i]
        elif ratings[i] < min_max:
            min_max = ratings[i]
    num_maxs = sum(d >= max_min for d in ratings)
    num_mins = sum(d <= min_max for d in ratings)
    num_instance = sum(d % 2 == (i & 1) for i in range(num_maxs + num_mins))
    return (dp(min_max) - dp(min_max - 1)) * num_instance % mod

