from typing import List
import heapq

def dijkstra(graph, start, end, visited):
    queue = [(0, start, '')]
    while queue:
        cost, current, path = heapq.heappop(queue)
        if current == end:
            return cost, path + chr(start)
        if current == start and visited == 0:
            return float('inf'), ''
        visited += 1
        for neighbor, cost in graph[current]:
            if neighbor not in path:
                new_cost, new_path = dijkstra(graph, neighbor, start, visited)
                if new_cost < cost:
                    heapq.heappush(queue, (new_cost, neighbor, new_path))
    return float('inf'), ''

def find_shortest_path(n, m, k, board):
    start = find_start(board)
    end = find_end(board)

    if start == -1 or end == -1:
        return "-1\n"

    graph = {}
    for i in range(n):
        for j in range(m):
            if board[i][j] == 'S':
                graph.setdefault((i, j), [])
                graph[(i, j)].append((start, 1))
            elif board[i][j] == 'T':
                graph.setdefault((i, j), [])
                graph[(i, j)].append((end, 1))
            elif board[i][j].isalpha():
                graph.setdefault((i, j), [])
                for dx, dy in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                    nx, ny = i + dx, j + dy
                    if 0 <= nx < n and 0 <= ny < m and board[nx][ny] != 'S' and board[nx][ny] != 'T':
                        graph[(i, j)].append((get_neighbor_position(i, j, dx, dy), 1))

    cost, path = dijkstra(graph, next(iter(graph.keys())), start, 0)

    if cost == float('inf'):
        return "-1\n"

    if path[0] == 'S' and path[-1] == 'T':
        return path[1:]
    else:
        return f"-1\n"

def get_neighbor_position(i, j, dx, dy):
    return i + dx, j + dy

def find_start(board):
    for i in range(len(board)):
        for j in range(len(board[0])):
            if board[i][j] == 'S':
                return i, j
    return -1

def find_end(board):
    for i in range(len(board)):
        for j in range(len(board[0])):
            if board[i][j] == 'T':
                return i, j
    return -1

