from typing import List

def find_minimal_path(n: int, m: int, k: int, board: List[str]) -> str:
    start, end = None, None
    paths = []

    for i in range(n):
        for j in range(m):
            if board[i][j] == 'S':
                start = (i, j)
            elif board[i][j] == 'T':
                end = (i, j)

    def is_valid(x, y):
        return 0 <= x < n and 0 <= y < m and board[x][y] != '_' and board[x][y] != 'T'

    def dijkstra():
        h, w = start
        dist = [[1_000_000] * w for _ in range(h)]
        dist[h][w] = 0
        pq = [(0, h, w)]
        while pq:
            cost, i, j = heapq.heappop(pq)
            if dist[i][j] < cost:
                continue
            for di, dj in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                ni, nj = i + di, j + dj
                if not is_valid(ni, nj):
                    continue
                alt = cost + 1
                if dist[ni][nj] > alt:
                    dist[ni][nj] = alt
                    heapq.heappush(pq, (alt, ni, nj))

        return dist[end[0]][end[1]]

    min_cost = dijkstra()
    min_path = []

    pq = [(min_cost, min_cost, start, start)]
    seen = set([start])

    while pq:
        cost, delta, v1, v2 = heapq.heappop(pq)
        if v1 == start and v2 == end:
            break
        for di, dj in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
            vi, vj = v1 + di, v2 + dj
            if vi < 0 or vi >= n or vj < 0 or vj >= m:
                continue
            if board[vi][vj] != '_' and (vi, vj) == start or (vi, vj) == end or (vi, vj) in seen:
                continue
            if board[vi][vj] == board[v1][v2]:
                seen.add((vi, vj))
                heapq.heappush(pq, (delta, delta+1, vi, vj))
            elif board[vi][vj] != board[v1][v2] and len(seen) == k and len(seen) < len(min_path):
                seen.add((vi, vj))
                heapq.heappush(pq, (cost, delta+1, vi, vj))
                min_path.append(board[vi][vj])

    if (end, start) in seen:
        min_path.append('_')
    elif (start, end) in seen:
        min_path.append('_')
    else:
        return ' '.join(min_path)
    return ''.join(min_path)

# Example usage
