from collections import defaultdict, deque


MOD = 10**9 + 7


def process_input():
    n, m = map(int, input().split())
    assert 1 <= n <= 10**5 and 1 <= m <= 10**5
    return n, m


def simplify_sat_formula(clauses):
    """
    Return a "deterministic" (i.e., it removes redundant ORs and XORs) truth table for a 2-XNF-2 formula.
    Input: a string containing clauses with literals
    Output: a dictionary mapping each possible combination of 2 literals to the result of the clause
    """
    literal_count = [0] * (2 * m + 1)
    literal_cache = defaultdict(int)
    d = defaultdict(int)
    for i, clause in enumerate(clauses):
        for literal in clause:
            if literal < 0:
                # literal_with_negation = literal * -1
                literal_cache[literal] += 1
                literal_count[-literal] += 1
            else:
                literal_cache[2 * i] += 1
                literal_count[i] += 1
    # Relax dependency relationships
    for index, value in literal_cache.items():
        for i in range(0, value):
            assert all(value_minus_cache_i // i == d[value_minus_cache_i] for value_minus_cache_i in literal_count if value_minus_cache_i % i == 0), value
            d[value] |= d[value_minus_cache_i] for value_minus_cache_i in literal_count if value_minus_cache_i % i == 0

    def check_sat(ixs):
        changes = {k: v for k, v in literal_cache.items() if k < 2 * m}
        sat = True
        for literal in ixs:
            changes[literal] -= literal
        for literal in literal_count:
