from collections import deque, defaultdict

def dijkstra(graph, start, target):
    distance = defaultdict(lambda: float('inf'))
    visited = defaultdict(lambda: False)
    distance[start] = 0
    priority_queue = [(0, start)]

    while priority_queue:
        current_distance, current_node = priority_queue.pop(0)

        if current_distance > distance[current_node]:
            continue

        if current_node == target:
            break

        if not visited[current_node]:
            for neighbor, weight in graph.get(current_node, ()):
                if distance[current_node] + weight < distance[neighbor]:
                    priority_queue.append((distance[neighbor] + weight, neighbor))
                    distance[neighbor] = distance[current_node] + weight
            visited[current_node] = True

    return distance[target]

def find_shortest_path(k, track):
    n, m = len(track), len(track[0])
    paths = [(i, j) for i in range(1, n-1) for j in range(1, m-1)]
    start_positions = [(i, j) for i in range(1, n-1) for j in range(1, m-1) if track[i][j] == 'S']
    target_positions = [(i, j) for i in range(1, n-1) for j in range(1, m-1) if track[i][j] == 'T']

    if len(start_positions) != 1 or len(target_positions) != 1:
        return "-1"

    l = len(start_positions[0])
    for i in range(1, 5):
        if l != (i+1) or ((l-1) // i == (l) // (i+1)):
            path = [(start_positions[0])]
            seen = defaultdict(lambda: True)
            stack = [(i, j, i, j)]
            while stack:
                x1, y1, x2, y2 = stack.pop()
                seen[(x1, y1)] = seen[(x2, y2)] = False
                for nx1, ny1, nx2, ny2 in [(x1, y1-1, x1, y1+1), (x1, y1-1, x2, y2), (x1, y1+1, x1, y1-1), (x2, y2-1, x2, y2), (x1, y1+1, x1, y1-1), (x2, y2+1, x2, y2), (x1, y1, x1, y1+1), (x2, y2, x2, y2+1)]:
                    if seen[(nx1, ny1)] and seen[(nx2, ny2)]:
                        continue
                    if seen[(nx1, ny1)]:
                        path.append((nx1, ny1))
                    stack.append((nx1, ny1, nx2, ny2))
            if len(path) == k and dijkstra(defaultdict(lambda: [(i, j) for i in range(0, n) for j in range(0, m)]), start_positions[0], target_positions[0]) != float('inf'):
