class FenwickTree:
    def __init__(self, n):
        self.n, self.t = n, [0] * n

    def update(self, i, val):
        for j in range(i + 1, self.n + 1):
            self.t[j - 1] += val

    def query(self, i):
        res = 0
        for j in range(i + 1, self.n + 1):
            res -= self.t[j - 1]
            self.update(j, 1)
        return res

