from typing import List, Tuple

def sort_array_with_cycles(n: int, s: int, arr: List[int]) -> Tuple[int, List[List[int]]]:
    def shift(arr: List[int], n: int) -> List[int]:
        return [(arr[i-1] if i > 0 else 0) for i in range(n)]

    total_length = sum(arr)
    if total_length > s:
        return (-1)

    seen = [False] * n
    current_length = 0
    for i in range(n):
        if seen[i]:
            continue
        current_length += 1
        seen[i] = True

        for j in range(i+1, n):
            if abs(arr[i]-arr[j]) <= s - current_length:
                seen[j] = True
                current_length -= 1

        if current_length == 0:
            total_length -= arr[i]

    ans = 0
    for i in range(n):
        current = arr[i]
        if seen[i]:
            while current != 1:
                next = (current + s - arr[i]) % n
                arr[i] = next
                if next == current:
                    break
                ans += 1

    return (ans, [[i+1] for i in range(n) if seen[i]])

# Example check function
