    visited[node] = False
    for neighbor in graph[node]:
        if neighbor == root or not visited[neighbor]:
            continue
        isBalanced = False
        (balanced, order) = balance(neighbor, graph, visited, order, root, node)
        if balanced:
            isBalanced = True
