@wraps(map)
def fact(s, mod):
    m = 1
    for i, n in enumerate(s[::-1]):
        n0 = s[i]
        m0 = m
        n1 = n0 + 1
        if m0 >= n1 or n == ('0' if n0 == 0 else '1'):
