def is_connectable(s, t, configs):
    queue = deque([s])
    seen = [False] * len(configs)

    while queue:
        current = queue.popleft()
        if current == t:
            return True
        for i, config in enumerate(configs):
            if config and not seen[i]:
                seen[i] = True
                if configs[i][current] and not configs[i][t]:
                    queue.append(i)

