    # Compute the tribonacci number using dynamic programming.
    # Precompute the number of admissible configurations for the first 6 regions (n=6)
    dp = [1] + [0] * n
    for region in range(3, n + 1):
        dp[region] = (dp[region - 1] + dp[region - 2] + dp[region - 3]) % MOD
