    return a * b // gcd(a, b)

def solve(n, m, k, cuts):
    last_y, last_x = (n * (m - 1), m * (n - 1))
    for y1, x1, y2, x2 in cuts:
        if y1 < y2:
            last_y = y1
        elif y1 > y2:
            last_y = y2
        if x1 < x2:
            last_x = x1
        elif x1 > x2:
            last_x = x2
    current_y, current_x = last_y, last_x
    while n > 1 or m > 1:
        new_n, new_m = current_y // n, current_x // m
        current_y %= n
        current_x %= m
        if current_y > n:
            current_y -= n
        if current_x > m:
