import sys
from functools import lru_cache

class Atcoder:
    def solve(self):
        n = int(input())
        s = input().strip()

        @lru_cache(None)
        def dfs(i, prev):
            if i == n:
                return 1
            count = 0
            for j in range(i+1, n):
                if s[j] == s[i]:
                    count += dfs(j, s[i])

            ret = 0
            for j in range(i+1, n):
                if prev == s[i] or s[j] == s[i]:
                    count2 = dfs(j, s[i]) if s[j] == s[i] else dfs(j, prev)
                    ret += count2
            return count * ret % 1000000007

        ans = 0
        for i in range(n):
            ans += dfs(i, s[i])
        print(ans % 1000000007)

atcoder = Atcoder()
